tokens.css:
--color-bg: #faf7f2;
--color-surface: #f5efe8;
--color-text: #222222;
--color-text-muted: #6b5d50;
--color-border: #e0d6cc;
--color-primary: #514134;
--color-on-primary: #ffffff;
--color-accent: #b8573a;
--color-on-accent: #ffffff;
--font-display: "Fraunces", Georgia, serif;
--font-body: "Work Sans", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 18px;
--text-lg: 23px;
--text-xl: 28px;
--text-2xl: 35px;
--text-3xl: 44px;
--radius-control: 6px;
--radius-card: 10px;
--space-section: 128px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
